-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 14
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 14 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 14', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 14 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-14.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que o questionário produz e o que a entrevista produz.', 0.2, 'O questionário produz dados quantitativos e padronizados, respondidos por muitas pessoas, que mostram tendências numéricas (quanto e com que frequência). A entrevista produz dados qualitativos e profundos, que explicam motivações, dúvidas e causas de uma dificuldade.', 'Nota cheia: separa com clareza o tipo de dado de cada método (questionário = número e padrão; entrevista = motivo e percepção) e usa as próprias palavras. Metade: cita só um dos dois métodos corretamente ou descreve os dois de forma vaga. Zero: em branco, inverte os métodos ou fala de outro assunto.'),
      (v_atividade, 1, 2, 'Indique qual método você aplicaria primeiro para medir quantos estudantes têm a dificuldade.', 0.4, 'Questionário, porque ele alcança muitos estudantes rapidamente e responde "quantos têm dificuldade" com números.', 'Nota cheia: indica o questionário como primeiro método e o liga à pergunta "quantos". Metade: indica o método certo sem ligar à pergunta, ou indica a entrevista com alguma justificativa válida. Zero: em branco, indica método errado sem justificativa ou não responde.'),
      (v_atividade, 1, 3, 'Justifique a escolha com base no objetivo do projeto.', 0.4, 'O objetivo tem duas partes: medir quantos estudantes têm dificuldade (quantitativo) e entender por que isso acontece (qualitativo). Como ainda não há pesquisa, o questionário inicial mapeia o cenário antes da entrevista, que aprofunda depois.', 'Nota cheia: justifica a escolha com o objetivo do projeto (medir quantidade primeiro) e menciona que nada foi pesquisado ainda. Metade: justifica de forma genérica, sem ligar ao objetivo do projeto. Zero: em branco, justificativa que não tem relação com o objetivo ou copiada.'),
      (v_atividade, 2, 1, 'Indique a estratégia para o pedido a e justifique.', 0.2, 'Para o app de agendamento com muitos usuários a alcançar rápido, o questionário, porque atinge dezenas de respondentes com custo baixo e respostas padronizadas.', 'Nota cheia: indica questionário e justifica pelo alcance amplo e rapidez. Metade: indica questionário sem justificar, ou justifica sem indicar o método. Zero: em branco, indica entrevista como método principal sem justificativa coerente ou não responde.'),
      (v_atividade, 2, 2, 'Indique a estratégia para o pedido b e justifique.', 0.4, 'Para a tela de cadastro em que os usuários travam sem se saber o motivo, a entrevista focada, porque explora dores, frustrações e causas profundas que um questionário de múltipla escolha não prevê.', 'Nota cheia: indica entrevista e justifica com a necessidade de descobrir o motivo (por que). Metade: indica entrevista sem justificar, ou indica questionário com justificativa parcial. Zero: em branco, método errado sem justificativa ou resposta fora do tema.'),
      (v_atividade, 2, 3, 'Indique a estratégia para o pedido c e justifique.', 0.4, 'Para o painel de relatórios que precisa de números para aprovação, o questionário com perguntas fechadas, porque gera dados quantitativos padronizados que sustentam a aprovação com números.', 'Nota cheia: indica questionário e liga o resultado a números e padronização para a aprovação. Metade: indica questionário sem ligar aos números, ou indica entrevista com justificativa parcial. Zero: em branco, método errado sem justificativa ou resposta fora do tema.'),
      (v_atividade, 3, 1, 'Explique o papel do questionário inicial nesta sequência.', 0.2, 'O questionário inicial mapeia hábitos e a frequência geral. Ele mostra que 60% evitam o módulo de provas, mas não explica o motivo; por isso é o primeiro passo.', 'Nota cheia: explica que o questionário mapeia o cenário geral e identifica o ponto de evasão, sem explicar o motivo. Metade: descreve o questionário de forma genérica, sem ligar ao caso dos 60%. Zero: em branco, fora do tema ou diz que o questionário explica o motivo.'),
      (v_atividade, 3, 2, 'Explique o papel da entrevista focada no ponto crítico.', 0.4, 'A entrevista focada investiga o ponto crítico levantado (o módulo de provas) para descobrir por que os estudantes evitam esse módulo, antes de qualquer desenho de tela.', 'Nota cheia: liga a entrevista ao ponto crítico (provas) e ao objetivo de descobrir o motivo. Metade: descreve a entrevista sem ligar ao ponto crítico. Zero: em branco, fora do tema ou atribui à entrevista a medição de percentuais.'),
      (v_atividade, 3, 3, 'Descreva como a validação cruzada compara as duas fontes.', 0.4, 'A validação cruzada compara as métricas do questionário (a porcentagem) com as histórias de uso relatadas nas entrevistas, verificando se as duas fontes apontam para o mesmo problema.', 'Nota cheia: explica a comparação entre números (questionário) e histórias de uso (entrevista) e sua finalidade de confirmar o achado. Metade: menciona a comparação sem explicar o que é comparado. Zero: em branco, fora do tema ou copiado sem explicação.'),
      (v_atividade, 4, 1, 'Descreva o formato de múltipla escolha fechada e quando usá-lo.', 0.2, 'Na múltipla escolha fechada, o respondente escolhe entre opções exclusivas ou em caixas de seleção. Usa-se quando o objetivo é obter respostas rápidas e padronizadas, como frequência de uso.', 'Nota cheia: descreve opções fechadas (exclusivas ou caixas de seleção) e indica quando usar (respostas rápidas e padronizadas, como frequência). Metade: descreve o formato sem indicar quando usar, ou o contrário. Zero: em branco, fora do tema ou descreve outro tipo de pergunta.'),
      (v_atividade, 4, 2, 'Descreva a escala de satisfação e indique seus extremos.', 0.4, 'A escala de satisfação usa notas de 1 a 5 ou níveis de concordância. Os extremos devem ser definidos, por exemplo 1 para muito difícil e 5 para muito fácil.', 'Nota cheia: descreve a escala (notas de 1 a 5 ou níveis de concordância) e indica os dois extremos com seus significados. Metade: descreve a escala sem os extremos, ou com extremos vagos. Zero: em branco, fora do tema ou não cita escala.'),
      (v_atividade, 4, 3, 'Descreva a pergunta aberta curta e explique por que ela deve ser limitada.', 0.4, 'A pergunta aberta curta permite comentário livre de até uma linha. Deve ser limitada para não cansar quem responde e para que as respostas possam ser tabuladas e categorizadas.', 'Nota cheia: descreve a pergunta aberta curta (espaço de uma linha) e explica a limitação pelo cansaço do respondente e pela tabulação. Metade: descreve a pergunta aberta sem explicar a limitação, ou explica a limitação sem descrever o formato. Zero: em branco, fora do tema ou copiado sem explicação.'),
      (v_atividade, 5, 1, 'Explique por que "O que você achou?" gera respostas vagas.', 0.2, '"O que você achou?" gera respostas vagas como "legal" ou "ok", porque não direciona a resposta a um aspecto mensurável, e por isso não permite comparar as respostas.', 'Nota cheia: explica que a pergunta é aberta e ampla, com respostas vagas (legal, ok), sem padrão de comparação. Metade: aponta que a resposta é vaga, sem explicar o motivo. Zero: em branco, fora do tema ou diz que a pergunta é boa.'),
      (v_atividade, 5, 2, 'Explique o que é uma escala como a Likert e para que ela serve.', 0.4, 'A escala Likert é uma escala numérica padronizada (por exemplo de 1 a 5) em que o respondente marca o grau de concordância ou de percepção. Serve para medir a percepção de forma comparável e tabulável.', 'Nota cheia: define a escala Likert como escala numérica padronizada e explica que serve para medir percepção de forma comparável. Metade: define a escala sem explicar sua utilidade, ou cita apenas "escala de notas" sem padrão. Zero: em branco, fora do tema ou confunde com outro tipo de pergunta.'),
      (v_atividade, 5, 3, 'Defina os dois extremos da escala para a facilidade de achar tarefas e justifique a escolha.', 0.4, 'Para a facilidade de achar tarefas, um extremo é 1 para muito difícil e o outro é 5 para muito fácil. Os extremos são definidos para que a nota tenha sentido sem interpretação.', 'Nota cheia: define os dois extremos com significados claros (muito difícil e muito fácil, ou equivalentes) e justifica a escolha pela clareza da interpretação. Metade: define os extremos sem justificar, ou justifica sem definir os dois extremos. Zero: em branco, fora do tema ou extremos sem relação com facilidade.'),
      (v_atividade, 6, 1, 'Identifique a pergunta indutora e explique o que ela induz.', 0.2, 'A pergunta indutora é "Você concorda que nosso menu azul ficou muito mais moderno e fácil de achar?". Ela induz a pessoa a concordar, por constrangimento ou sugestão direta, porque já traz a conclusão na frase.', 'Nota cheia: identifica a primeira pergunta como indutora e explica que ela induz a concordância (já traz a opinião pronta). Metade: identifica a pergunta certa sem explicar o que induz. Zero: em branco, aponta a pergunta neutra como indutora ou não responde.'),
      (v_atividade, 6, 2, 'Explique por que a pergunta neutra permite a percepção real do usuário.', 0.4, 'A pergunta neutra ("Como você avalia a facilidade para encontrar o menu principal?") não traz opinião embutida e deixa o usuário expressar sua percepção real, sem pressão.', 'Nota cheia: explica que a pergunta não traz juízo nem sugestão e por isso captura a percepção real do usuário. Metade: diz que é neutra sem explicar por que captura a percepção real. Zero: em branco, fora do tema ou diz que a pergunta neutra induz.'),
      (v_atividade, 6, 3, 'Explique o risco que os dados falsos trazem para a fase de programação.', 0.4, 'Dados falsos, gerados por perguntas tendenciosas, levam a decisões erradas de projeto. Na fase de programação, isso significa construir funções e telas baseadas em uma percepção que não é real, com retrabalho.', 'Nota cheia: explica que dados enviesados levam a decisões erradas e a retrabalho na programação. Metade: diz que os dados são ruins, sem ligar à programação. Zero: em branco, fora do tema ou diz que dados falsos não têm impacto.'),
      (v_atividade, 7, 1, 'Indique o que revisar em cada pergunta com adjetivo opinativo.', 0.2, 'Em cada pergunta com adjetivo opinativo, deve-se trocar o adjetivo por uma descrição neutra e observável, ou por uma escala, para que a pergunta não já traga um julgamento (por exemplo, "fácil" ou "bonito").', 'Nota cheia: indica substituir o adjetivo opinativo por descrição neutra ou escala, e explica que o adjetivo induz a resposta. Metade: indica revisar o adjetivo sem explicar como ou por quê. Zero: em branco, fora do tema ou sugere manter os adjetivos.'),
      (v_atividade, 7, 2, 'Explique por que a pergunta sobre o tempo gasto é mais segura.', 0.4, 'A pergunta sobre o tempo gasto no formulário é mais segura porque mede um fato observável (um número de minutos), e não uma opinião, então não depende de julgamento do respondente.', 'Nota cheia: explica que o tempo é um fato mensurável e não uma opinião, por isso não induz. Metade: diz que é mais segura sem explicar por quê. Zero: em branco, fora do tema ou diz que é uma pergunta opinativa.'),
      (v_atividade, 7, 3, 'Descreva a verificação de perguntas indutoras que deve ser feita antes da coleta.', 0.4, 'Antes da coleta, deve-se conferir cada pergunta com a pergunta "ela já traz a resposta?" ou se induz a concordar, e reescrever as que induzem, testando o roteiro com perguntas neutras.', 'Nota cheia: descreve uma verificação concreta (checar cada pergunta por indução, reescrever as indutoras) feita antes da coleta. Metade: menciona a verificação de forma genérica ("revisar as perguntas"). Zero: em branco, fora do tema ou não menciona verificação.'),
      (v_atividade, 8, 1, 'Explique o risco de um formulário longo para quem responde.', 0.2, 'Um formulário longo causa desistência em massa: quem responde se cansa, abandona e deixa dados incompletos. Questionários com mais de 10 perguntas sofrem essa desistência.', 'Nota cheia: explica que o cansaço leva à desistência e a dados incompletos, citando o limite de cerca de 10 perguntas. Metade: diz que o formulário longo cansa, sem explicar a desistência. Zero: em branco, fora do tema ou diz que formulário longo é melhor.'),
      (v_atividade, 8, 2, 'Indique como priorizar as perguntas que realmente respondem ao objetivo da pesquisa.', 0.4, 'Priorizar as perguntas que respondem ao objetivo da pesquisa: manter as que trazem a informação necessária e cortar as que não ajudam a decidir, respeitando o limite de tamanho e o tempo do público (intervalo das aulas).', 'Nota cheia: indica um critério de priorização ligado ao objetivo da pesquisa e ao público do intervalo, com cortes concretos. Metade: indica priorizar sem critério claro. Zero: em branco, fora do tema ou propõe manter todas as 22 perguntas.'),
      (v_atividade, 8, 3, 'Explique como a redução preserva a qualidade dos dados.', 0.4, 'Reduzir o formulário preserva a qualidade dos dados porque mantém as perguntas que medem o objetivo e aumenta a taxa de resposta completa, evitando dados incompletos de quem desistiu.', 'Nota cheia: explica que a redução mantém as perguntas do objetivo e melhora a completude dos dados. Metade: diz que a redução ajuda sem explicar a relação com a qualidade. Zero: em branco, fora do tema ou diz que reduzir piora os dados.'),
      (v_atividade, 9, 1, 'Descreva o bloco de acolhimento e seu objetivo.', 0.2, 'O bloco de acolhimento é o início da entrevista: explica o objetivo da conversa e tranquiliza o entrevistado, para que ele se sinta confortável.', 'Nota cheia: descreve o acolhimento como explicação do objetivo e tranquilização do entrevistado. Metade: descreve só um dos dois elementos. Zero: em branco, fora do tema ou descreve outra etapa.'),
      (v_atividade, 9, 2, 'Descreva o bloco de contexto e o tipo de pergunta feita nele.', 0.4, 'O bloco de contexto vem depois do acolhimento e faz perguntas sobre hábitos do dia a dia do entrevistado, para entender a rotina em que o aplicativo é usado.', 'Nota cheia: indica o contexto como bloco de hábitos e rotina do dia a dia e o tipo de pergunta (sobre hábitos, rotinas). Metade: descreve o bloco de forma genérica, sem o tipo de pergunta. Zero: em branco, fora do tema ou confunde com desafios.'),
      (v_atividade, 9, 3, 'Descreva o bloco de desafios e explique por que ele vem depois do contexto.', 0.4, 'O bloco de desafios pede exemplos de dificuldades que o entrevistado encontra nas telas. Vem depois do contexto porque, antes de perguntar sobre dificuldades, é preciso conhecer a rotina de uso para que os exemplos sejam concretos.', 'Nota cheia: descreve o bloco como pedido de exemplos de dificuldades e explica a ordem pelo contexto (a rotina serve de base para os exemplos). Metade: descreve o bloco sem explicar por que vem depois. Zero: em branco, fora do tema ou inverte a ordem sem justificativa.'),
      (v_atividade, 10, 1, 'Explique a etapa de agradecimento e o que ela envolve.', 0.2, 'A etapa de agradecimento fecha a sessão de forma cordial, agradecendo o tempo e a participação do entrevistado, e marca o fim da conversa.', 'Nota cheia: descreve o agradecimento como fechamento cordial da sessão, com reconhecimento da participação. Metade: menciona agradecer sem explicar o que envolve. Zero: em branco, fora do tema ou não menciona o agradecimento.'),
      (v_atividade, 10, 2, 'Explique por que as falas devem ser registradas de forma literal.', 0.4, 'As falas devem ser registradas literalmente para preservar as palavras reais do usuário, sem resumos ou correções, porque o sentido exato e as expressões usadas são evidência para a equipe.', 'Nota cheia: explica que o registro literal preserva a fala real e evita interpretações do pesquisador. Metade: diz que deve ser literal sem explicar a razão. Zero: em branco, fora do tema ou defende resumir ou corrigir as falas.'),
      (v_atividade, 10, 3, 'Descreva o que deve constar no registro logo após a entrevista.', 0.4, 'Logo após a entrevista deve-se registrar as falas literais, a data, o perfil do entrevistado e as observações relevantes da sessão, enquanto a memória ainda está fresca.', 'Nota cheia: cita falas literais e pelo menos mais um item do registro (data, perfil ou observações), registrado logo após a sessão. Metade: cita só um item, ou registro sem indicar o momento. Zero: em branco, fora do tema ou registro que não inclui as falas.'),
      (v_atividade, 11, 1, 'Escreva uma pergunta que leve a um episódio concreto recente.', 0.2, 'Uma pergunta que leva a um episódio concreto recente é "Me conte sobre a última vez em que você tentou achar a sua média no aplicativo?". Ela pede um fato real, não uma opinião sobre o futuro.', 'Nota cheia: escreve uma pergunta que pede um episódio recente e específico (a última vez, uma situação real). Metade: pergunta que pede um exemplo, mas sem ser recente ou concreto. Zero: em branco, pergunta fechada ou pergunta sobre o futuro.'),
      (v_atividade, 11, 2, 'Escreva uma pergunta que revele o que o estudante esperava que acontecesse.', 0.4, 'Uma pergunta que revela a expectativa é "O que você esperava que acontecesse quando clicou nesse botão?". Ela mostra o modelo mental do usuário e o descompasso com a tela.', 'Nota cheia: escreve pergunta sobre o que o usuário esperava, sem sugerir resposta, e ligada ao descompasso com a tela. Metade: pergunta sobre expectativa, mas indutora ou sem ligação com a tela. Zero: em branco, pergunta fechada ou indutora.'),
      (v_atividade, 11, 3, 'Escreva uma pergunta que descubra a causa raiz do incômodo.', 0.4, 'Uma pergunta que descobre a causa raiz é "Por que esse detalhe te incomodou?". Ela vai além do sintoma (a tela é confusa) e busca o motivo do incômodo.', 'Nota cheia: escreve pergunta do tipo "por que" sobre o incômodo, que busca a causa e não o sintoma. Metade: pergunta sobre o incômodo, mas que fica no sintoma. Zero: em branco, pergunta fechada ou fora do tema.'),
      (v_atividade, 12, 1, 'Explique por que você não deve interromper nem rebater a crítica.', 0.2, 'O consultor não deve interromper nem rebater, porque a crítica emocional contém um fato a ser entendido; rebater fecha a conversa e impede o estudante de explicar o problema real.', 'Nota cheia: explica que rebater ou interromper bloqueia o relato e impede entender o fato por trás da emoção. Metade: diz que não deve rebater, sem explicar o prejuízo. Zero: em branco, fora do tema ou sugere defender o sistema.'),
      (v_atividade, 12, 2, 'Escreva a pergunta que pede a tarefa que o colega tentava realizar.', 0.4, '"Qual tarefa você estava tentando realizar quando isso aconteceu?"', 'Nota cheia: pergunta que pede a tarefa que o colega tentava realizar (qual tarefa, o que queria fazer). Metade: pergunta sobre o problema, sem pedir a tarefa. Zero: em branco, fora do tema ou pergunta que defende o sistema.'),
      (v_atividade, 12, 3, 'Escreva a pergunta que pede um exemplo concreto do que aconteceu na tela.', 0.4, '"Pode me dar um exemplo concreto do que aconteceu na tela?"', 'Nota cheia: pergunta que pede um exemplo concreto do que aconteceu na tela (fato técnico). Metade: pede exemplo sem referência à tela. Zero: em branco, pergunta fechada ou fora do tema.'),
      (v_atividade, 13, 1, 'Explique o que é parafrasear na escuta ativa.', 0.2, 'Parafrasear é repetir com as suas palavras o que o entrevistado disse, para confirmar que você entendeu corretamente antes de seguir.', 'Nota cheia: explica parafrasear como repetir com outras palavras o que foi dito, para confirmar o entendimento. Metade: diz que é repetir, sem a finalidade de confirmar. Zero: em branco, fora do tema ou confunde com copiar a fala sem conferir.'),
      (v_atividade, 13, 2, 'Escreva a frase de confirmação com as palavras do estudante.', 0.4, '"Entendi que o botão de consulta é pequeno e some na tela, certo?"', 'Nota cheia: frase de confirmação que usa os termos do estudante (botão pequeno, some na tela) e termina com pedido de confirmação. Metade: frase de confirmação sem os termos do estudante, ou com termos alterados. Zero: em branco, fora do tema ou frase que já julga ou opina.'),
      (v_atividade, 13, 3, 'Explique o que se ganha ao confirmar o entendimento antes de registrar o fato.', 0.4, 'Confirmar antes de registrar evita registrar um fato errado. Assim, o que vai para o caderno é o que o estudante quis dizer, e os dados ficam confiáveis para a equipe.', 'Nota cheia: explica que a confirmação evita registrar um entendimento errado e garante dados confiáveis. Metade: diz que a confirmação é importante, sem explicar o ganho. Zero: em branco, fora do tema ou diz que não é necessário confirmar.'),
      (v_atividade, 14, 1, 'Diferencie dados quantitativos de dados qualitativos.', 0.2, 'Dados quantitativos respondem "quanto", "quantos" e "com que frequência", são numéricos e medidos em grandes grupos. Dados qualitativos respondem "por que" e "como", explicam emoções, dúvidas e causas.', 'Nota cheia: diferencia os dois tipos pelo que respondem (números e tendências x motivos e causas). Metade: diferencia sem exemplos ou com um dos tipos apenas. Zero: em branco, fora do tema ou inverte os conceitos.'),
      (v_atividade, 14, 2, 'Associe a pergunta "quantos" a um tipo de dado e a um método.', 0.4, 'A pergunta "quantos" é quantitativa e se responde com um questionário de opções fechadas, que gera contagens (por exemplo, quantos estudantes têm dificuldade para achar as provas).', 'Nota cheia: associa "quantos" a dado quantitativo e a questionário com opções fechadas. Metade: associa ao tipo certo sem o método, ou ao método sem o tipo. Zero: em branco, fora do tema ou associa a entrevista.'),
      (v_atividade, 14, 3, 'Associe a pergunta "por que" a um tipo de dado e a um método.', 0.4, 'A pergunta "por que" é qualitativa e se responde com entrevista em profundidade ou observação direta, que explicam as causas da dificuldade.', 'Nota cheia: associa "por que" a dado qualitativo e a entrevista (ou observação) que explora causas. Metade: associa ao tipo certo sem o método, ou ao método sem o tipo. Zero: em branco, fora do tema ou associa a questionário fechado.'),
      (v_atividade, 15, 1, 'Explique o que é o dilema do palpite nesse caso.', 0.2, 'O dilema do palpite acontece quando se projeta a tela com base no gosto pessoal, sem perguntar aos usuários. Escolhas técnicas viram palpites pessoais, e não decisões fundamentadas.', 'Nota cheia: explica o palpite como decisão de design tomada por gosto, sem dados dos usuários. Metade: descreve a proposta sem usar o conceito de palpite. Zero: em branco, fora do tema ou defende projetar pelo gosto.'),
      (v_atividade, 15, 2, 'Explique por que escolhas técnicas sem dados viram palpites arriscados.', 0.4, 'Sem dados, a escolha técnica não tem fundamento na necessidade real. Por isso, ela pode gastar semanas em botões que ninguém usa, como acontece com a média final no caso do aplicativo de notas.', 'Nota cheia: explica que sem dados a escolha não reflete a necessidade real e pode gerar retrabalho ou ajuste em algo que não resolve o problema. Metade: diz que é arriscado, sem explicar o motivo. Zero: em branco, fora do tema ou diz que dados não importam.'),
      (v_atividade, 15, 3, 'Descreva a coleta que você faria antes de desenhar a tela.', 0.4, 'Antes de desenhar a tela, faria uma coleta com estudantes e professores: um questionário para medir quantos têm dificuldade e entrevistas para entender por que (por exemplo, para achar a média final).', 'Nota cheia: descreve uma coleta concreta, com pelo menos um método e público (estudantes e professores), feita antes do desenho. Metade: descreve a coleta sem o público ou o método. Zero: em branco, fora do tema ou propõe desenhar antes de coletar.'),
      (v_atividade, 16, 1, 'Explique por que o consultor não julga o usuário nem assume o que ele prefere.', 0.2, 'O consultor não julga o usuário nem assume o que ele prefere, porque sua tarefa é observar fatos. Se ele impõe a própria opinião ou concorda com tudo, o dado deixa de representar o usuário.', 'Nota cheia: explica que julgar ou assumir a preferência do usuário contamina o dado e que a função é observar fatos. Metade: diz que não deve julgar, sem explicar o efeito nos dados. Zero: em branco, fora do tema ou diz que o consultor deve impor a opinião.'),
      (v_atividade, 16, 2, 'Descreva como observar fatos e ouvir com atenção, sem impor a sua opinião.', 0.4, 'Deve-se observar fatos, como o que o usuário faz na tela, e ouvir com atenção, sem impor opinião, por exemplo registrando o comportamento e pedindo exemplos em vez de concordar.', 'Nota cheia: descreve observar fatos e ouvir com atenção, com uma prática concreta que não impõe opinião. Metade: descreve observar e ouvir de forma genérica. Zero: em branco, fora do tema ou descreve impor a opinião.'),
      (v_atividade, 16, 3, 'Explique como a postura neutra garante que o diagnóstico seja respeitado.', 0.4, 'A postura neutra garante que o diagnóstico reflita o que o usuário vivencia. Por isso, desenvolvedores e clientes respeitam o diagnóstico: ele se baseia em fatos e não em preferências do consultor.', 'Nota cheia: explica que a neutralidade deixa o diagnóstico baseado em fatos, o que faz com que seja respeitado. Metade: diz que a neutralidade ajuda, sem explicar a relação com o respeito ao diagnóstico. Zero: em branco, fora do tema ou diz que a opinião pessoal é mais confiável.'),
      (v_atividade, 17, 1, 'Explique o prejuízo do formulário com mais de 10 perguntas.', 0.2, 'Um formulário com mais de 10 perguntas sofre desistência em massa: quem responde se cansa e abandona, o que deixa a amostra pequena e os dados incompletos.', 'Nota cheia: explica a desistência em massa e o prejuízo na amostra e na completude dos dados. Metade: diz que é longo e prejudica, sem explicar o efeito nos dados. Zero: em branco, fora do tema ou diz que o formulário longo não prejudica.'),
      (v_atividade, 17, 2, 'Explique por que completar a fala do entrevistado impede a dúvida real.', 0.4, 'Ao completar a frase, o entrevistador impõe a sua palavra e impede o entrevistado de expressar a dúvida real, o que faz o dado registrar o que o consultor imaginou e não o que o usuário pensa.', 'Nota cheia: explica que completar a fala impõe a visão do entrevistador e impede a dúvida real do entrevistado. Metade: diz que é errado, sem explicar o efeito no dado. Zero: em branco, fora do tema ou defende completar a fala.'),
      (v_atividade, 17, 3, 'Explique por que não se devem descartar relatos estranhos sem investigação.', 0.4, 'Relatos estranhos podem indicar falhas graves no sistema. Descartá-los sem investigação faz perder problemas reais, por isso é preciso investigar antes de decidir se o relato é relevante.', 'Nota cheia: explica que relatos estranhos podem apontar falhas graves e que o descarte sem investigação esconde problemas reais. Metade: diz que não deve descartar, sem explicar o risco. Zero: em branco, fora do tema ou diz que relatos estranhos devem ser descartados.'),
      (v_atividade, 18, 1, 'Escreva o que fazer antes da coleta.', 0.2, 'Antes da coleta, definir o objetivo específico, revisar se não há perguntas indutoras e preparar o roteiro ou o formulário.', 'Nota cheia: cita o objetivo específico e a revisão de perguntas indutoras (ou equivalente). Metade: cita um dos dois itens. Zero: em branco, fora do tema ou ações que não são de preparação.'),
      (v_atividade, 18, 2, 'Escreva o que fazer durante a coleta.', 0.4, 'Durante a coleta, gravar ou anotar as falas literais, sem resumir nem corrigir o português da pessoa, e seguir o roteiro com neutralidade.', 'Nota cheia: cita as falas literais (sem resumir nem corrigir) e a postura neutra durante a coleta. Metade: cita só um desses itens. Zero: em branco, fora do tema ou ações que alteram as falas.'),
      (v_atividade, 18, 3, 'Escreva o que fazer depois da coleta, até a apresentação à equipe.', 0.4, 'Depois da coleta, tabular os dados em planilha compartilhada e montar gráficos para apresentar à equipe, até a apresentação.', 'Nota cheia: cita a tabulação em planilha (ou equivalente) e a montagem de gráficos para apresentar à equipe. Metade: cita só a tabulação ou só o gráfico. Zero: em branco, fora do tema ou ações que não ocorrem depois da coleta.'),
      (v_atividade, 19, 1, 'Explique a etapa de limpeza e o que ela elimina.', 0.2, 'A limpeza elimina respostas incompletas ou duplicadas, deixando apenas dados válidos para a análise.', 'Nota cheia: explica que a limpeza elimina respostas incompletas e duplicadas. Metade: cita só um dos dois tipos ou diz "organizar" sem indicar o que é eliminado. Zero: em branco, fora do tema ou diz que a limpeza mantém tudo.'),
      (v_atividade, 19, 2, 'Explique a etapa de agrupamento e a etapa de categorização das falas abertas.', 0.4, 'O agrupamento soma as contagens de notas idênticas. A categorização cria tags temáticas para reunir as falas abertas com o mesmo sentido, como "Legibilidade e Contraste" ou "Navegação e Layout", e quantificar a frequência de cada dificuldade.', 'Nota cheia: explica o agrupamento (somar contagens de respostas iguais) e a categorização (criar tags para falas com o mesmo sentido) com a finalidade de contar. Metade: explica só um dos dois conceitos. Zero: em branco, fora do tema ou confunde os dois conceitos sem explicação.'),
      (v_atividade, 19, 3, 'Explique a etapa de visualização e o que ela permite à equipe.', 0.4, 'A visualização gera gráficos para leitura rápida, que mostram as prioridades e permitem à equipe identificar de imediato o maior obstáculo e decidir o que entra no protótipo.', 'Nota cheia: explica que a visualização gera gráficos que tornam as prioridades visíveis e apoiam a decisão da equipe. Metade: diz que gera gráficos, sem explicar o que a equipe ganha. Zero: em branco, fora do tema ou não menciona gráficos.'),
      (v_atividade, 20, 1, 'Indique a evidência que sustenta a decisão e explique por que ela é um fato.', 0.2, 'A evidência é o gráfico de dificuldades da turma, que mostra "achar notas" com 18 respostas, à frente de senha perdida e lentidão. É um fato porque é um número contado a partir da coleta, e não uma opinião.', 'Nota cheia: indica a evidência do gráfico (o fluxo de consulta de notas como maior obstáculo) e explica que é fato por ser contagem da coleta. Metade: indica a evidência sem explicar por que é fato. Zero: em branco, fora do tema ou usa opinião como evidência.'),
      (v_atividade, 20, 2, 'Proponha uma decisão de interface que responda à evidência.', 0.4, 'Criar um destaque fixo no topo da tela inicial para o acesso às notas (por exemplo, um atalho ou card de consulta de notas), para que o estudante consiga chegar ao fluxo de consulta sem vários cliques.', 'Nota cheia: propõe uma decisão concreta de interface (atalho, card ou destaque) ligada diretamente ao fluxo de consulta de notas. Metade: propõe uma mudança de interface sem ligação direta à evidência. Zero: em branco, fora do tema ou decisão que não responde à evidência.'),
      (v_atividade, 20, 3, 'Descreva o impacto esperado da decisão para o estudante.', 0.4, 'O impacto esperado é que o estudante acesse as notas com um toque, sem cliques repetidos, eliminando a frustração e o atraso na consulta.', 'Nota cheia: descreve o impacto para o estudante (acesso mais rápido, com menos cliques ou toques, menos frustração). Metade: descreve um impacto genérico, como "melhorar a experiência", sem ligação com a decisão. Zero: em branco, fora do tema ou impacto para a equipe e não para o estudante.');
end $$;
